from build123d import *
import math

def hypocycloid(t, r1, r2):
    return ((r1 - r2) * math.cos(t) + r2 * math.cos(r1 / r2 * t - t),
            (r1 - r2) * math.sin(t) + r2 * math.sin(-(r1 / r2 * t - t)))

def epicycloid(t, r1, r2):
    return ((r1 + r2) * math.cos(t) - r2 * math.cos(r1 / r2 * t + t),
            (r1 + r2) * math.sin(t) - r2 * math.sin(r1 / r2 * t + t))

def gear_point(t, r1=30, r2=5):
    if (-1) ** (1 + math.floor(t / (2 * math.pi) * (r1 / r2))) < 0:
        return epicycloid(t, r1, r2)
    else:
        return hypocycloid(t, r1, r2)

num_samples = 300
outer_pts = [gear_point(i * 2 * math.pi / num_samples) for i in range(num_samples + 1)]

with BuildPart() as p:
    with BuildSketch() as s:
        Polygon(*outer_pts)
    extrude(amount=8)

solid_body = p.part
solid_body = fillet(solid_body.edges(), 2)

hole_radius = 10
hole_positions = [(0, 0)]
for i in range(3):
    angle = math.radians(90 + i * 120)
    x = 30 * math.cos(angle)
    y = 30 * math.sin(angle)
    hole_positions.append((x, y))

for x, y in hole_positions:
    solid_body = solid_body - Pos(x, y, 0) * Cylinder(hole_radius, 20)

part = solid_body
part.name = "gear_with_holes"
export_step(part, "output.step")
